odoo.template:
const CACHE = 'creart-app-v2';
const OFFLINE = '/creart/app/sin-conexion';
const SHELL = [
    OFFLINE,
    '/crm_extended_3D/static/src/app/creart_app.css?v=2',
    '/crm_extended_3D/static/src/app/creart_app.js?v=2',
    '/crm_extended_3D/static/src/app/icon-192.png',
];
self.addEventListener('install', (event) => {
    event.waitUntil(caches.open(CACHE).then((cache) => cache.addAll(SHELL)));
    self.skipWaiting();
});
self.addEventListener('activate', (event) => {
    event.waitUntil(caches.keys().then((keys) => Promise.all(
        keys.filter((key) => key !== CACHE).map((key) => caches.delete(key))
    )));
    self.clients.claim();
});
self.addEventListener('fetch', (event) => {
    if (event.request.mode === 'navigate') {
        // Los datos de clientes nunca se guardan en el dispositivo.
        event.respondWith(fetch(event.request).catch(() => caches.match(OFFLINE)));
        return;
    }
    const url = new URL(event.request.url);
    if (SHELL.includes(url.pathname + url.search)) {
        event.respondWith(caches.match(event.request).then((hit) => hit || fetch(event.request)));
    }
});
